{
  "title": "The Rescue of Prince Aldwin",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Dawn over the ruined royal city.",
      "visual_description": "Wide establishing shot of a broken skyline, crumbling spires, and tattered banners flapping above empty streets at sunrise.",
      "characters": ["Captain Maren"]
    },
    {
      "scene_number": 2,
      "caption": "The rescue party gathers at the outer ridge.",
      "visual_description": "Four figures crouched on a rocky overlook, studying the city below, packs and weapons laid out on the stone.",
      "characters": ["Captain Maren", "Brin the Scout", "Vesna the Mage", "Old Tobin"]
    },
    {
      "scene_number": 3,
      "caption": "Brin unfolds the stolen map.",
      "visual_description": "Close-up of a worn parchment map weighted by stones, marked with red ink showing tower routes and the dungeon where the captive is held.",
      "characters": ["Brin the Scout", "Captain Maren"]
    },
    {
      "scene_number": 4,
      "caption": "They slip past the rusted castle gates.",
      "visual_description": "Massive iron gates hanging askew, vines crawling through bars, the team sneaking single-file through a narrow gap.",
      "characters": ["Captain Maren", "Brin the Scout", "Vesna the Mage", "Old Tobin"]
    },
    {
      "scene_number": 5,
      "caption": "A cursed tower looms, but they ignore it.",
      "visual_description": "Blackened spiral tower pulsing with faint purple light; the party walks past in the foreground, eyes forward, refusing to look up.",
      "characters": ["Captain Maren", "Vesna the Mage", "Brin the Scout", "Old Tobin"]
    },
    {
      "scene_number": 6,
      "caption": "Frightened townspeople whisper of a dragon.",
      "visual_description": "A huddle of ragged citizens in a doorway, gesturing toward the sky, while Maren kneels to listen, hand raised in calm.",
      "characters": ["Captain Maren", "Mira the Baker", "Old Tobin"]
    },
    {
      "scene_number": 7,
      "caption": "Old Tobin dozes against a fallen statue.",
      "visual_description": "Comic beat: Tobin snoring under a toppled stone king, his hat tipped over his eyes, while Brin pokes him with a stick.",
      "characters": ["Old Tobin", "Brin the Scout"]
    },
    {
      "scene_number": 8,
      "caption": "An armored patrol marches through the square.",
      "visual_description": "Column of black-plated soldiers crossing a rubble-strewn plaza; the party hides behind an overturned cart, breath held.",
      "characters": ["Captain Maren", "Brin the Scout", "Vesna the Mage", "Old Tobin", "Iron Sergeant Korv"]
    },
    {
      "scene_number": 9,
      "caption": "Vesna silences a creaking banner with a whisper.",
      "visual_description": "Tattered royal banner above the team; Vesna's fingers trace a glowing rune, freezing the cloth mid-flap as the patrol passes below.",
      "characters": ["Vesna the Mage", "Captain Maren"]
    },
    {
      "scene_number": 10,
      "caption": "They find the sealed magic door to the dungeon.",
      "visual_description": "An ornate stone door covered in glowing blue sigils set into a moss-covered wall; Vesna studies it while the others guard the corridor.",
      "characters": ["Vesna the Mage", "Captain Maren", "Brin the Scout", "Old Tobin"]
    },
    {
      "scene_number": 11,
      "caption": "Vesna unravels the binding spell.",
      "visual_description": "Close-up of glowing sigils unwinding into floating sparks, reflected in Vesna's wide eyes, her staff tip pressed to the central rune.",
      "characters": ["Vesna the Mage"]
    },
    {
      "scene_number": 12,
      "caption": "Inside the dungeon, they find Prince Aldwin.",
      "visual_description": "A thin young man in torn finery chained to a damp stone wall, blinking at the torchlight as Maren rushes forward with a key.",
      "characters": ["Captain Maren", "Prince Aldwin", "Brin the Scout"]
    },
    {
      "scene_number": 13,
      "caption": "The prince can barely walk; Tobin carries him.",
      "visual_description": "Old Tobin, suddenly wide awake, hoisting the prince on his broad back, surprising the others with his strength.",
      "characters": ["Old Tobin", "Prince Aldwin", "Captain Maren"]
    },
    {
      "scene_number": 14,
      "caption": "Iron Sergeant Korv blocks the corridor.",
      "visual_description": "A towering armored figure with a glaive at the end of a torchlit hallway, helm reflecting flame, the party skidding to a halt.",
      "characters": ["Iron Sergeant Korv", "Captain Maren", "Brin the Scout", "Vesna the Mage", "Old Tobin", "Prince Aldwin"]
    },
    {
      "scene_number": 15,
      "caption": "Maren duels the sergeant while the others flee.",
      "visual_description": "Sparks fly as Maren's sword locks against Korv's glaive; in the background, the rest of the team sprints toward a stairway of light.",
      "characters": ["Captain Maren", "Iron Sergeant Korv"]
    },
    {
      "scene_number": 16,
      "caption": "A dragon's shadow sweeps over the rooftops.",
      "visual_description": "Huge winged silhouette darkening the broken streets; the fleeing team ducks under an archway as scaled wingtips brush the spires.",
      "characters": ["Brin the Scout", "Vesna the Mage", "Old Tobin", "Prince Aldwin"]
    },
    {
      "scene_number": 17,
      "caption": "They reach the half-collapsed bridge at the city's edge.",
      "visual_description": "A long stone bridge with gaps over a churning river; Maren catches up bloodied but alive as the party steps onto the first cracked span.",
      "characters": ["Captain Maren", "Brin the Scout", "Vesna the Mage", "Old Tobin", "Prince Aldwin"]
    },
    {
      "scene_number": 18,
      "caption": "Across the bridge, into the morning light.",
      "visual_description": "Silhouettes of the five crossing toward green hills, the ruined city receding behind them under a brightening sky.",
      "characters": ["Captain Maren", "Brin the Scout", "Vesna the Mage", "Old Tobin", "Prince Aldwin"]
    }
  ]
}

